"""Original four-paw beast and two-handed handler action guides."""
import json
import produce as p
UID='unit_mireclaw_moonbite_mirehorn_breakers'
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original MIREHORN BREAKER group from the supplied painting, facing SCREEN RIGHT. Exactly ONE massive four-legged gray olive swamp beast with exactly FOUR clawed paws, TWO forelegs and TWO hindlegs, not arms. Exactly TWO large black ivory crescent horns, one ivory bone faceplate, original amber eyes, closed mouth, gold nose ring, wicker limb cuffs, bronze reed harness, tall reed-and-leaf back mantle, attached original amber lanterns on their unchanged fine chains. Exactly ONE small leaf-clad humanoid handler behind-left with exactly TWO arms, TWO legs and two feet. His left hand holds the ONE crooked wooden lantern staff planted beside him; his right hand grips the ONE dark rein attached to the beast harness. Preserve both hands and grips, original hooked staff length/top lantern, reed hood, cloth and pale hand/face markings. No extra horns, lanterns, hands, legs, characters or equipment. The handler stays beside the same beast. Same painted fantasy artwork, scale and locked camera. ')
PLATE=(' Entire background flat magenta RGB255,0,255, no scenery, shadows, floor marks, text, zoom, camera movement or cuts. Fixed ground reference y576. Keep horn tips, reed mantle, whole staff, all paws, handler feet and chains inside generous canvas margins throughout. No growing lights, sparks, magic, smoke, fireball, projectile, detached emission or invented weapon. Original lantern glow remains enclosed in the original lanterns. ')
def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8
 return f

def recipe(clip,indices,guides,last,action,seed):
 out=p.SOURCE_DIR/(clip+'_h3_v1');assert not out.exists();out.mkdir()
 c=dict(unit_id=UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=[reference(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip,flush=True)
if __name__=='__main__':
 recipe('move',[11,2,3],[[32,1],[78,2]],0,'One complete reciprocal grounded walking cycle IN PLACE. Near forepaw and far hindpaw advance together, then the far forepaw and near hindpaw advance, each paw lowers to bear weight before the opposed pair lifts. No jumping or rearing. The handler walks in place beside the beast with alternating grounded two-foot steps, left staff grip and right rein grip continuous. Slight natural shoulder/reed/lantern sway, no horizontal travel or sliding. Return smoothly to the exact initial ready. ',2026110301)
 recipe('attack',[11,4,5],[[32,1],[62,2]],0,'One physical grounded horn-and-shoulder ram SCREEN RIGHT. Lower intact head and brace four paws into the supplied windup, thrust head/shoulder forward once with horns angled for contact, handler leans back while keeping both grips and grounded feet. Short anchored lunge only. Recover head and all four paws back to ready. No bite, repeated ram, disappearing horns, detaching rein or magical flash. ',2026110302)
 recipe('hit',[11,7],[[48,1]],0,'One restrained impact recoil. Beast head/shoulders flinch backward and original four paws absorb the impact, handler leans back one step and steadies staff/rein without letting go. Head remains screen right and all limbs/horns intact. Recover smoothly to ready, no fall or repeated hits. ',2026110303)
 recipe('defend',[11,6],[],1,'One continuous defensive brace. Beast lowers its head and broad shoulders into supplied four-paw compact guard, handler crouches firmly beside it with planted staff and taut rein. Hold that guarded pose for the last second. No kneeling collapse, return to ready, shield or new props. ',2026110304)
 recipe('cast',[11,6,1],[[38,1],[76,2]],0,'One distinct physical supportive salutation. Beast slowly bows its intact horned head while handler bows beside it retaining both original grips; then handler straightens and lifts the hooked staff slightly in a reassuring salute as beast raises its head, original attached lanterns gently swing. Lower staff and recover both figures to ready. This is a calm deliberate bow-and-salute, no attack, spell, mouth emission, projectile or new lamp. ',2026110305)
 recipe('death',[11,8,9,10],[[38,1],[77,2]],3,'One continuous gravity-driven collapse of BOTH figures. Beast front knees buckle, shoulders lower, then near side settles onto the fixed ground plane into original corpse. Handler loses balance beside it, bends knees and falls onto his near side beside the beast, with both hands and the single staff/rein retained as in supplied corpse. Four beast paws fold naturally; two handler legs settle. Horns, reeds, all chains and original lanterns stay attached without merging or growing. No pose replacement, dissolve, spinning, standing back up, shrinkage or vanishing handler. End both figures fully grounded and motionless for the final second. ',2026110306)
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','hit','defend','cast','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='All19 original poses and curated identity inspected; exact four-paw beast, two-arm/two-leg handler, left staff/right rein grips and original grounded corpse. Preserve accepted eight-pose idle260ms. Six new H3 actions require full source, enlarged alpha and actual native/mirror/live review. Melee unit retains ranged-to-attack fallback, no authored ranged claim.')))
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,output_scale=.5,canvas=[960,640],ground_anchor=[480,576],ready_guide=reference(11),corpse_guide=reference(10),reason='Inherited anatomical scales and grounded anchors from actual original pose packing retained per source. Accepted idle11 supplies common ready; original four-paw guide poses and group corpse retain original physical contacts. Fixed outputscale, no bounding-box normalization, per-frame shift, warp or invented articulation.'))
